/**
 * pageTitle — renders the sp-page-title section:
 *   - slider (home)   : fotorama slider chunk
 *   - breadcrumb (def): Главная / ... / <pagetitle>
 *   - none            : empty
 */
$mode = 'breadcrumb';
$title = '';
if ($modx->resource) {
    $tv = $modx->resource->getTVValue('title_mode');
    if ($tv !== null && $tv !== '') $mode = $tv;
    $title = $modx->resource->get('pagetitle');
    $intro = $modx->resource->get('introtext');
    if ($intro !== null && trim($intro) !== '' && $modx->resource->get('parent')) {
        // news items store full title in introtext
        $title = $intro;
    }
}
if ($mode === 'none') return '';
if ($mode === 'slider') {
    return $modx->getChunk('slider');
}

$esc = function ($s) {
    return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8');
};
$url = function ($id) use ($modx, $esc) {
    $u = $modx->makeUrl($id);
    if ($u === '' || $u === null) return '/';
    if (strpos($u, 'http') === 0 || $u[0] === '/') return $esc($u);
    return $esc('/' . $u);
};

$ancestors = array();
if ($modx->resource) {
    $parent = (int)$modx->resource->get('parent');
    $siteStart = (int)$modx->config['site_start'];
    while ($parent > 0 && $parent !== $siteStart) {
        $p = $modx->getObject('modResource', $parent);
        if (!$p || !$p->get('published')) break;
        $ancestors[] = $p;
        $parent = (int)$p->get('parent');
    }
    $ancestors = array_reverse($ancestors);
}

$t = $esc($title);
$homeUrl = $url($modx->config['site_start']);

$out  = '<section id="sp-page-title" class="tz-page-head"><div class="container"><div class="row">'
      . '<div id="sp-title" class="col-sm-12 col-md-12"><div class="sp-column"><div class="sp-module">'
      . '<div class="sp-module-content">' . "\n";
$out .= '<nav class="tz-breadcrumb-wrap" aria-label="Навигация">' . "\n";
$out .= '<ol class="breadcrumb tz-breadcrumb">' . "\n";
$out .= "\t" . '<li class="tz-breadcrumb-home"><a href="' . $homeUrl . '" class="pathway">'
      . '<i class="fa fa-home" aria-hidden="true"></i><span>Главная</span></a></li>' . "\n";

foreach ($ancestors as $ancestor) {
    if ((int)$ancestor->get('id') === (int)$modx->resource->get('id')) continue;
    $out .= "\t" . '<li><a href="' . $url($ancestor->get('id')) . '" class="pathway">'
          . $esc($ancestor->get('pagetitle')) . '</a></li>' . "\n";
}

$out .= "\t" . '<li class="active" aria-current="page">' . $t . '</li>' . "\n";
$out .= '</ol></nav>' . "\n";
$out .= '</div></div></div></div></div></div></section>';
return $out;

